def cmd_init(argv):
    if "-h" in argv or "--help" in argv:
        sys.stdout.write(sub_help("init"))
        return 0
    if "-V" in argv or "--version" in argv:
        sys.stdout.write(VERSION)
        return 0
    cmd = "z"
    hook = "pwd"
    no_cmd = False
    shell = None
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--no-cmd" or arg == "--no-aliases":
            no_cmd = True
        elif arg == "--cmd":
            cmd, i = parse_value(argv, i, "--cmd <CMD>", "executable init [OPTIONS] <SHELL>")
            continue
        elif arg.startswith("--cmd="):
            cmd = arg.split("=", 1)[1]
        elif arg == "--hook":
            hook, i = parse_value(argv, i, "--hook <HOOK>", "executable init [OPTIONS] <SHELL>")
            continue
        elif arg.startswith("--hook="):
            hook = arg.split("=", 1)[1]
        elif arg.startswith("-"):
            return unexpected_arg_error(arg, "executable init <SHELL>")
        elif shell is None:
            shell = arg
        else:
            return unexpected_arg_error(arg, "executable init [OPTIONS] <SHELL>", tip=False)
        i += 1
    if shell is None:
        return usage_error("the following required arguments were not provided:
  <SHELL>", "executable init <SHELL>")
    allowed = {"bash", "elvish", "fish", "ksh", "nushell", "posix", "powershell", "tcsh", "xonsh", "zsh"}
    if shell not in allowed:
        return invalid_value_error(shell, "<SHELL>", "bash, elvish, fish, nushell, posix, powershell, tcsh, xonsh, zsh")
    if hook not in {"none", "prompt", "pwd"}:
        return invalid_value_error(hook, "--hook <HOOK>", "none, prompt, pwd")
    sys.stdout.write(shell_script(shell, cmd=cmd, hook=hook, no_cmd=no_cmd))
    return 0


def autojump_rank(value):
    return 1.0 / (1.0 + math.exp(-value))


