def parse_z(lines):
    rows = []
    for line in lines:
        if not line.strip():
            continue
        parts = line.rsplit("|", 2)
        if len(parts) != 3:
            short = line.split("|")
            if len(short) == 2 and rows:
                raise ZoxideError(f"import error

Caused by:
    0: invalid epoch: {short[1]}
    1: invalid digit found in string")
            if len(short) == 2:
                raise ZoxideError(f"import error

Caused by:
    0: invalid rank: {short[0]}
    1: invalid float literal")
            raise ZoxideError(f"import error

Caused by:
    invalid entry: {line}")
        path, rank_text, epoch_text = parts
        try:
            rank = float(rank_text)
        except ValueError:
            raise ZoxideError(f"import error

Caused by:
    0: invalid rank: {rank_text}
    1: invalid float literal")
        try:
            epoch = int(epoch_text)
        except ValueError:
            raise ZoxideError(f"import error

Caused by:
    0: invalid epoch: {epoch_text}
    1: invalid digit found in string")
        upsert(rows, path, rank, float(epoch))
    return rows


def cmd_import(argv):
    if "-h" in argv or "--help" in argv:
        sys.stdout.write(sub_help("import"))
        return 0
    if "-V" in argv or "--version" in argv:
        sys.stdout.write(VERSION)
        return 0
    command_preamble()
    source = None
    merge = False
    path = None
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--from":
            if source is not None:
                return usage_error("the argument '--from <FROM>' cannot be used multiple times", "executable import [OPTIONS] --from <FROM> <PATH>")
            source, i = parse_value(argv, i, "--from <FROM>", "executable import [OPTIONS] --from <FROM> <PATH>")
            continue
        if arg.startswith("--from="):
            if source is not None:
                return usage_error("the argument '--from <FROM>' cannot be used multiple times", "executable import [OPTIONS] --from <FROM> <PATH>")
            source = arg.split("=", 1)[1]
        elif arg == "--merge":
            merge = True
        elif arg.startswith("-"):
            return unexpected_arg_error(arg, "executable import [OPTIONS] --from <FROM> <PATH>")
        else:
            path = arg
        i += 1
    missing = []
    if source is None:
        missing.append("--from <FROM>")
    if path is None:
        missing.append("<PATH>")
    if missing:
        return usage_error("the following required arguments were not provided:
  " + "
  ".join(missing), "executable import --from <FROM> <PATH>")
    if source not in {"autojump", "z", "fasd"}:
        return invalid_value_error(source, "--from <FROM>", "autojump, z")
    rows = load_db()
    if rows and not merge:
        return zoxide_error("current database is not empty, specify --merge to continue anyway")
    try:
        lines = open(path, "r", encoding="utf-8", errors="surrogateescape").read().splitlines()
    except OSError as exc:
        return zoxide_error(f"could not open database for importing: {path}

Caused by:
    {exc.strerror} (os error {exc.errno})")
    imported = parse_autojump(lines) if source == "autojump" else parse_z(lines)
    if not merge:
        rows = []
    for row in imported:
        upsert(rows, row["path"], row["rank"], row["last_access"])
    rows = apply_aging(rows)
    save_db(rows)
    return 0


def cmd_edit(argv):
    if "-h" in argv or "--help" in argv:
        sys.stdout.write(sub_help("edit"))
        return 0
    if "-V" in argv or "--version" in argv:
        sys.stdout.write(VERSION)
        return 0
    command_preamble()
    if not argv:
        return zoxide_error("could not find fzf, is it installed?")
    for arg in argv:
        if arg.startswith("-"):
            return unexpected_arg_error(arg, "executable edit", tip=False)
    sub = argv[0]
    rows = load_db()
    if sub == "reload":
        rows = apply_aging(rows)
        save_db(rows)
        output_edit_rows(rows)
        return 0
    if len(argv) < 2:
        return usage_error("the following required arguments were not provided:
  <PATH>", "executable edit [COMMAND] <PATH>")
    path = argv[1]
    if sub == "increment":
        upsert(rows, path, 1.0, time.time())
    elif sub == "decrement":
        upsert(rows, path, -1.0, time.time())
    elif sub == "delete":
        rows = [row for row in rows if row["path"] != path]
    else:
        return usage_error(f"unrecognized subcommand '{sub}'", "executable edit [COMMAND] [PATH]")
    rows = apply_aging(rows)
    save_db(rows)
    output_edit_rows(rows)
    return 0


def main(argv):
    try:
        if not argv:
            sys.stderr.write(MAIN_HELP)
            return 2
        if argv[0] in ("-h", "--help"):
            sys.stdout.write(MAIN_HELP)
            return 0
        if argv[0] in ("-V", "--version"):
            sys.stdout.write(VERSION)
            return 0
        if argv[0].startswith("-"):
            return unexpected_arg_error(argv[0], "executable <COMMAND>", tip=False)
        command, rest = argv[0], argv[1:]
        if command == "add":
            return cmd_add(rest)
        if command == "query":
            return cmd_query(rest)
        if command == "remove":
            return cmd_remove(rest)
        if command == "init":
            return cmd_init(rest)
        if command == "import":
            return cmd_import(rest)
        if command == "edit":
            return cmd_edit(rest)
        if command.lower() in {"add", "query", "remove", "init", "import", "edit"}:
            eprint(f"error: unrecognized subcommand '{command}'")
            eprint()
            if command != command.upper():
                eprint(f"  tip: a similar subcommand exists: '{command.lower()}'")
                eprint()
            eprint("Usage: executable <COMMAND>")
            eprint()
            eprint("For more information, try '--help'.")
            return 2
        return usage_error(f"unrecognized subcommand '{command}'", "executable <COMMAND>")
    except UsageExit as exc:
        return exc.code
    except ZoxideError as exc:
        return zoxide_error(str(exc))


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))

