def cmd_add(argv):
    if "-h" in argv or "--help" in argv:
        sys.stdout.write(sub_help("add"))
        return 0
    if "-V" in argv or "--version" in argv:
        sys.stdout.write(VERSION)
        return 0
    command_preamble()
    score = 1.0
    saw_score = False
    paths = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--":
            paths.extend(argv[i + 1:])
            break
        if arg in ("-s", "--score"):
            if saw_score:
                return usage_error("the argument '--score <SCORE>' cannot be used multiple times", "executable add [OPTIONS] <PATHS>...")
            saw_score = True
            value, i = parse_value(argv, i, "--score <SCORE>", "executable add [OPTIONS] <PATHS>...")
            score = parse_float(value, "--score <SCORE>", "executable add [OPTIONS] <PATHS>...")
            continue
        if arg.startswith("--score="):
            if saw_score:
                return usage_error("the argument '--score <SCORE>' cannot be used multiple times", "executable add [OPTIONS] <PATHS>...")
            saw_score = True
            score = parse_float(arg.split("=", 1)[1], "--score <SCORE>", "executable add [OPTIONS] <PATHS>...")
            i += 1
            continue
        if arg.startswith("-"):
            return unexpected_arg_error(arg, "executable add [OPTIONS] <PATHS>...")
        paths.append(arg)
        i += 1
    if not paths:
        return usage_error("the following required arguments were not provided:
  <PATHS>...", "executable add <PATHS>...")
    if any(path == "" for path in paths):
        return simple_error("a value is required for '<PATHS>...' but none was supplied")
    normalized = []
    for raw in paths:
        if has_excluded_chars(raw):
            continue
        path = norm_path(raw)
        if excluded(path):
            continue
        if not os.path.isdir(path):
            return zoxide_error(f"not a directory: {path}")
        normalized.append(path)
    rows = load_db()
    for path in normalized:
        upsert(rows, path, score, time.time())
    rows = apply_aging(rows)
    save_db(rows)
    return 0


def keyword_match(path, keywords, strict_last=True):
    keys = [key for key in keywords if key != ""]
    if not keys:
        return True
    text = path.replace("\", "/").lower()
    normalized = [key.replace("\", "/").lower() for key in keys]
    last_key = normalized[-1]
    idx = text.rfind(last_key)
    if idx < 0:
        return False
    if strict_last and "/" in text[idx + len(last_key):]:
        return False
    text = text[:idx]
    for key in reversed(normalized[:-1]):
        idx = text.rfind(key)
        if idx < 0:
            return False
        text = text[:idx]
    return True


def matching_rows(rows, keywords, show_all, exclude_path, base_dir, strict_last=True):
    visible = list(rows)
    before_exclude = [row for row in visible if keyword_match(row["path"], keywords, strict_last=strict_last)]
    if exclude_path:
        ex = norm_path(exclude_path)
        visible = [row for row in visible if norm_path(row["path"]) != ex]
    if base_dir:
        base = norm_path(base_dir)
        visible = [row for row in visible if norm_path(row["path"]).startswith(base)]
    visible = [row for row in visible if not excluded(row["path"])]
    if not show_all:
        visible = [row for row in visible if os.path.isdir(row["path"])]
    matched = [row for row in visible if keyword_match(row["path"], keywords, strict_last=strict_last)]
    matched.sort(key=lambda row: (-display_score(row), -row.get("rank", 0.0), len(row["path"]), row["path"]))
    return before_exclude, matched


def cmd_query(argv):
    if "-h" in argv or "--help" in argv:
        sys.stdout.write(sub_help("query"))
        return 0
    if "-V" in argv or "--version" in argv:
        sys.stdout.write(VERSION)
        return 0
    command_preamble()
    show_all = False
    interactive = False
    list_mode = False
    score_mode = False
    exclude_path = None
    base_dir = None
    keywords = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--":
            keywords.extend(argv[i + 1:])
            break
        if arg in ("-a", "--all"):
            show_all = True
        elif arg in ("-i", "--interactive"):
            interactive = True
        elif arg in ("-l", "--list"):
            list_mode = True
        elif arg in ("-s", "--score"):
            score_mode = True
        elif arg == "--exclude":
            exclude_path, i = parse_value(argv, i, "--exclude <path>", "executable query [OPTIONS] [KEYWORDS]...")
            continue
        elif arg.startswith("--exclude="):
            exclude_path = arg.split("=", 1)[1]
        elif arg == "--base-dir":
            base_dir, i = parse_value(argv, i, "--base-dir <path>", "executable query [OPTIONS] [KEYWORDS]...")
            continue
        elif arg.startswith("--base-dir="):
            base_dir = arg.split("=", 1)[1]
        elif arg.startswith("-"):
            return unexpected_arg_error(arg, "executable query [OPTIONS] [KEYWORDS]...")
        else:
            keywords.append(arg)
        i += 1
    if interactive and list_mode:
        return usage_error("the argument '--interactive' cannot be used with '--list'", "executable query --interactive [KEYWORDS]...")
    rows = apply_aging(load_db())
    save_db(rows)
    before_exclude, rows = matching_rows(rows, keywords, show_all, exclude_path, base_dir, strict_last=not interactive)
    if interactive:
        return run_interactive(rows, score_mode)
    if not rows:
        if list_mode:
            return 0
        if exclude_path and before_exclude:
            return zoxide_error("you are already in the only match")
        return zoxide_error("no match found")
    output_query_rows(rows if list_mode else rows[:1], score_mode)
    return 0


def run_interactive(rows, score_mode):
    fzf = shutil.which("fzf")
    if not fzf:
        return zoxide_error("could not find fzf, is it installed?")
    if not rows:
        return zoxide_error("no match found")
    args = [fzf, "--exact", "--no-sort", "--exit-0", "--delimiter=	", "--nth=2", "--read0"]
    if os.name != "nt":
        args.append("--preview=echo {2}")
    custom = os.environ.get("_ZO_FZF_OPTS")
    if custom:
        args.extend(custom.split())
    feed = "".join(f"{display_score(row):.4f}	{row['path']}\0" for row in rows)
    proc = subprocess.run(args, input=feed, capture_output=True, text=True)
    if proc.returncode == 130:
        return 130
    if proc.returncode == 1:
        return zoxide_error("no match found")
    if proc.returncode == 2:
        return zoxide_error("fzf returned an error")
    if 128 <= proc.returncode <= 254:
        return zoxide_error("fzf was terminated")
    selection = proc.stdout
    if not selection or "	" not in selection or len(selection) < 7:
        return zoxide_error("could not read selection from fzf")
    if score_mode:
        sys.stdout.write(selection)
    else:
        sys.stdout.write(selection.split("	", 1)[1])
    return 0


def cmd_remove(argv):
    if "-h" in argv or "--help" in argv:
        sys.stdout.write(sub_help("remove"))
        return 0
    if "-V" in argv or "--version" in argv:
        sys.stdout.write(VERSION)
        return 0
    command_preamble()
    paths = []
    for arg in argv:
        if arg == "--":
            continue
        if arg.startswith("-"):
            return unexpected_arg_error(arg, "executable remove [PATHS]...")
        paths.append(norm_path(arg))
    if not paths:
        return 0
    rows = load_db()
    existing = {row["path"] for row in rows}
    seen = set()
    for path in paths:
        if path in seen or path not in existing:
            return zoxide_error(f"path not found in database: {path}")
        seen.add(path)
    rows = [row for row in rows if row["path"] not in seen]
    save_db(rows)
    return 0


def init_template_source(shell):
    if shell == "ksh":
        shell = "posix"
    names = [
        os.path.join(os.path.dirname(os.path.abspath(__file__)), "templates", f"{shell}.txt"),
        os.path.join(os.getcwd(), "templates", f"{shell}.txt"),
    ]
    for path in names:
        if os.path.exists(path):
            return open(path, "r", encoding="utf-8").read()
    return FALLBACK_TEMPLATES.get(shell)


def template_tokens(source):
    i = 0
    while i < len(source):
        start = i
        while True:
            start = source.find("{", start)
            if start < 0 or start + 1 >= len(source):
                break
            if source[start + 1] in "{%#":
                break
            start += 1
        if start < 0 or start + 1 >= len(source):
            yield "text", source[i:]
            return
        marker = source[start + 1]
        if start > i:
            yield "text", source[i:start]
        close = {"{": "}}", "%": "%}", "#": "#}"}[marker]
        if marker == "{":
            end = start + 2
            quoted = False
            escaped = False
            while end < len(source) - 1:
                char = source[end]
                if escaped:
                    escaped = False
                elif char == "\" and quoted:
                    escaped = True
                elif char == '"':
                    quoted = not quoted
                elif not quoted and source.startswith(close, end):
                    break
                end += 1
            end = end if end < len(source) - 1 else -1
        else:
            end = source.find(close, start + 2)
        if end < 0:
            yield "text", source[start:]
            return
        token = source[start:end + 2]
        i = end + 2
        yield marker, token


def strip_template_token(token, marker):
    left_trim = token.startswith("{{-") or token.startswith("{%-") or token.startswith("{#-")
    right_trim = token.endswith("-}}") or token.endswith("-%}") or token.endswith("-#}")
    left = 3 if left_trim else 2
    right = -3 if right_trim else -2
    return token[left:right].strip(), left_trim, right_trim


def hook_name(value):
    return {"none": "None", "prompt": "Prompt", "pwd": "Pwd"}.get(value, value)


def eval_template_expr(expr, ctx):
    expr = expr.strip()
    if expr in ctx:
        value = ctx[expr]
        return "" if value is None else str(value)
    if expr.startswith('"') and expr.endswith('"'):
        try:
            return str(ast.literal_eval(expr))
        except Exception:
            return expr[1:-1]
    match = re.fullmatch(r'cmd\.unwrap_or\("([^"]*)"\)', expr)
    if match:
        return str(ctx.get("cmd") or match.group(1))
    return ""


def eval_template_condition(expr, ctx):
    expr = expr.strip()
    if expr == "echo":
        return bool(ctx.get("echo"))
    if expr == "resolve_symlinks":
        return bool(ctx.get("resolve_symlinks"))
    if expr == "cfg!(windows)":
        return False
    if expr == "cmd":
        return ctx.get("cmd") is not None
    match = re.fullmatch(r"hook\s*([!=]=)\s*InitHook::(\w+)", expr)
    if match:
        current = hook_name(str(ctx.get("hook")))
        wanted = match.group(2)
        return (current == wanted) if match.group(1) == "==" else (current != wanted)
    if expr == "let Some(cmd) = cmd":
        return ctx.get("cmd") is not None
    return False


def render_init_template(source, cmd, hook, echo, resolve_symlinks):
    ctx = {
        "cmd": cmd,
        "hook": hook,
        "echo": echo,
        "resolve_symlinks": resolve_symlinks,
    }
    out = ""
    trim_next = False
    stack = []

    def active():
        return all(frame["active"] for frame in stack)

    for marker, token in template_tokens(source):
        if marker == "text":
            text = token
            if trim_next:
                text = re.sub(r"^[ 	
]+", "", text)
                trim_next = False
            if active():
                out += text
            continue

        expr, left_trim, right_trim = strip_template_token(token, marker)
        if left_trim and active():
            out = out.rstrip(" 	
")
        if marker == "#":
            trim_next = right_trim
            continue
        if marker == "{":
            if active():
                out += eval_template_expr(expr, ctx)
            trim_next = right_trim
            continue

        parent_active = active()
        if expr.startswith("let "):
            if parent_active:
                match = re.fullmatch(r"let\s+(\w+)(?:\s*=\s*(.*))?", expr, re.DOTALL)
                if match:
                    name, value = match.group(1), match.group(2)
                    ctx[name] = eval_template_expr(value, ctx) if value is not None else ctx.get(name, "")
        elif expr.startswith("if "):
            cond = expr[3:].strip()
            value = parent_active and eval_template_condition(cond, ctx)
            stack.append({"kind": "if", "parent": parent_active, "active": value, "taken": value})
        elif expr.startswith("else if "):
            frame = stack[-1]
            cond = expr[8:].strip()
            value = frame["parent"] and not frame["taken"] and eval_template_condition(cond, ctx)
            frame["active"] = value
            frame["taken"] = frame["taken"] or value
        elif expr == "else":
            frame = stack[-1]
            frame["active"] = frame["parent"] and not frame["taken"]
            frame["taken"] = True
        elif expr == "endif":
            stack.pop()
        elif expr.startswith("match "):
            name = expr[6:].strip()
            value = ctx.get(name)
            stack.append({"kind": "match", "parent": parent_active, "active": False, "taken": False, "value": value})
        elif expr.startswith("when "):
            frame = stack[-1]
            choice = expr[5:].strip()
            value = False
            if choice.startswith("Some"):
                value = frame["value"] is not None
            elif choice == "None":
                value = frame["value"] is None
            elif choice.startswith("InitHook::"):
                value = hook_name(str(frame["value"])) == choice.split("::", 1)[1]
            frame["active"] = frame["parent"] and not frame["taken"] and value
            frame["taken"] = frame["taken"] or frame["active"]
        elif expr == "endmatch":
            stack.pop()
        trim_next = right_trim
    return out.replace("
## Hook to add new entries to the database.", "
#

# Hook to add new entries to the database.")


