            hook = arg.split("=", 1)[1]
        elif arg.startswith("-"):
            return unexpected_arg_error(arg, "executable init <SHELL>")
        elif shell is None:
            shell = arg
        else:
            return unexpected_arg_error(arg, "executable init [OPTIONS] <SHELL>", tip=False)
        i += 1
    if shell is None:
        return usage_error("the following required arguments were not provided:
  <SHELL>", "executable init <SHELL>")
    allowed = {"bash", "elvish", "fish", "ksh", "nushell", "posix", "powershell", "tcsh", "xonsh", "zsh"}
    if shell not in allowed:
        return invalid_value_error(shell, "<SHELL>", "bash, elvish, fish, nushell, posix, powershell, tcsh, xonsh, zsh")
    if hook not in {"none", "prompt", "pwd"}:
        return invalid_value_error(hook, "--hook <HOOK>", "none, prompt, pwd")
    sys.stdout.write(shell_script(shell, cmd=cmd, hook=hook, no_cmd=no_cmd))
    return 0


